// nap-art.js — le carte napoletane, as one lazily-loaded module.
//
// All 40 cards are traced from a Neapolitan-pattern deck printed in Naples in
// 1902 (Bibliothèque nationale de France, via Gallica): stencilled woodcut,
// Asso-Sette plus Fante, Cavallo, Re in denari, coppe, spade and bastoni. The
// Asso di Denari still carries the Regno d'Italia duty stamp and the printer's
// address; the back is the deck's own tumbling-blocks lattice. Same contract
// as the other deck modules: napSVG(id, {dark}) returns a standalone SVG.

const W=250, H=388;

const SUITS_IT = { d: 'Denari', c: 'Coppe', s: 'Spade', b: 'Bastoni' };
const RANKS_IT = { '01': 'Asso', '02': 'Due', '03': 'Tre', '04': 'Quattro', '05': 'Cinque',
  '06': 'Sei', '07': 'Sette', F: 'Fante', C: 'Cavallo', R: 'Re' };
const RANK_ORDER = ['01', '02', '03', '04', '05', '06', '07', 'F', 'C', 'R'];

export const NAP_IDS = (() => {
  const ids = [];
  for (const su of ['d', 'c', 's', 'b']) for (const r of RANK_ORDER) ids.push(su + r);
  return ids;
})();

export function napMeta(id) {
  const suit = SUITS_IT[id[0]], rank = id.slice(1);
  return { id, suit, rank, label: `${RANKS_IT[rank]} di ${suit}` };
}

function shell(inner, { dark = true } = {}) {
  const c = dark
    ? { face: '#15171A', ink: '#DCE0E4', brassLine: '#B99450', hair: '#2A2E33' }
    : { face: '#F6F3EC', ink: '#23262B', brassLine: '#8A6B2F', hair: '#D8D2C4' };
  return `<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg">
    <rect x="1.5" y="1.5" width="${W - 3}" height="${H - 3}" rx="13" fill="${c.face}" stroke="${c.hair}" stroke-width="1.5"/>
    ${inner(c)}
  </svg>`;
}

const fmt = n => Math.round(n * 100) / 100;

function tracedCard(id, { dark = true } = {}) {
  const art = FRAGS[id], meta = napMeta(id);
  return shell((c) => {
    const s = Math.min(206 / art.w, 306 / art.h);
    const w = art.w * s, hh = art.h * s, ox = (W - w) / 2, oy = 18 + (312 - hh) / 2;
    let out = `<rect x="11" y="11" width="${W - 22}" height="${H - 22}" rx="7" fill="none" stroke="${c.brassLine}" stroke-width="1.4" opacity="0.85"/>`;
    out += `<svg x="${fmt(ox)}" y="${fmt(oy)}" width="${fmt(w)}" height="${fmt(hh)}" viewBox="0 0 ${art.w} ${art.h}" color="${c.ink}" opacity="0.96">${art.g}</svg>`;
    out += `<line x1="30" y1="342" x2="${W - 30}" y2="342" stroke="${c.brassLine}" stroke-width="0.7" opacity="0.5"/>`;
    out += `<text x="${W / 2}" y="366" text-anchor="middle" font-family="Iosevka Etoile,Georgia,serif" font-size="15" letter-spacing="0.04em" fill="${c.ink}" opacity="0.92">${meta.label}</text>`;
    return out;
  }, { dark });
}

// The deck's own back: the 1902 printer's tumbling-blocks lattice — a wall of
// little cubes, which could hardly suit this app better.
function backCard({ dark = true } = {}) {
  const art = FRAGS.back;
  return shell((c) => {
    const s = Math.min(216 / art.w, 354 / art.h);
    const w = art.w * s, hh = art.h * s, ox = (W - w) / 2, oy = (H - hh) / 2;
    let out = `<rect x="9" y="9" width="${W - 18}" height="${H - 18}" rx="8" fill="none" stroke="${c.brassLine}" stroke-width="1.5"/>`;
    out += `<svg x="${fmt(ox)}" y="${fmt(oy)}" width="${fmt(w)}" height="${fmt(hh)}" viewBox="0 0 ${art.w} ${art.h}" color="${c.brassLine}" opacity="0.9">${art.g}</svg>`;
    return out;
  }, { dark });
}

export function napSVG(id, { dark = true } = {}) {
  if (id === 'back') return backCard({ dark });
  return tracedCard(id, { dark });
}

